import{b as a,O as e,g as o,j as r}from"./chunks/framework.DcaUmd3X.js";const q=JSON.parse('{"title":"持续交付中的测试（上）—— 管道与原则","description":"","frontmatter":{},"headers":[],"relativePath":"testing/engineering/continuous-delivery-1/index.md","filePath":"测试理论与实践/4.现代测试工程/14.持续交付（上）.md","lastUpdated":1781625968000}'),n={name:"testing/engineering/continuous-delivery-1/index.md"};function d(i,t,l,s,h,u){return e(),o("div",null,[...t[0]||(t[0]=[r(`<h1 id="持续交付中的测试-上-——-管道与原则" tabindex="-1">持续交付中的测试（上）—— 管道与原则 <a class="header-anchor" href="#持续交付中的测试-上-——-管道与原则" aria-label="Permalink to &quot;持续交付中的测试（上）—— 管道与原则&quot;">​</a></h1><blockquote><p>前面各章讲的测试方法、策略、角色，最终都要落到一条自动化的流水线上——这就是部署管道。它让测试从&quot;人的记忆&quot;变成&quot;机器的记忆&quot;，每一次提交都自动验证。</p></blockquote><h2 id="什么是部署管道" tabindex="-1">什么是部署管道 <a class="header-anchor" href="#什么是部署管道" aria-label="Permalink to &quot;什么是部署管道&quot;">​</a></h2><p>部署管道（Deployment Pipeline）是《持续交付》的核心概念。它是一个自动化的流程：<strong>代码从提交到上线，中间经过一系列阶段，每个阶段都是一道质量闸门。</strong></p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>代码提交 → 提交阶段 → 验收阶段 → 容量阶段 → 手动阶段 → 生产发布</span></span>
<span class="line"><span>(触发)    (几分钟)  (几十分钟) (几小时)    (按需)    (最终)</span></span></code></pre></div><p>管道的核心思想是：<strong>每次提交都生成一个发布候选，通过逐级验证来判断它是否适合上线。</strong> 某道闸门没通过，候选就被拒绝，不会流到下一个阶段。</p><p>这跟传统测试流程最大的区别在于——不是&quot;所有测试做完了再判断能不能上&quot;，而是<strong>越早的阶段越快、越轻量、发现问题越早</strong>。提交阶段挂了，几分钟就知道了；不要等到容量阶段发现一个提交阶段就能发现的低级错误。</p><h2 id="管道四阶段" tabindex="-1">管道四阶段 <a class="header-anchor" href="#管道四阶段" aria-label="Permalink to &quot;管道四阶段&quot;">​</a></h2><h3 id="提交阶段-最快的反馈" tabindex="-1">提交阶段：最快的反馈 <a class="header-anchor" href="#提交阶段-最快的反馈" aria-label="Permalink to &quot;提交阶段：最快的反馈&quot;">​</a></h3><p>代码提交后自动触发。目标是：<strong>在几分钟内回答&quot;这次改动有没有把基本的东西搞坏&quot;。</strong></p><table tabindex="0"><thead><tr><th>做什么</th><th>工具</th><th>时间预算</th></tr></thead><tbody><tr><td>编译（如果有）</td><td>语言编译器</td><td>—</td></tr><tr><td>所有小型测试（Q1）</td><td>JUnit / pytest / Jest</td><td>—</td></tr><tr><td>静态代码分析</td><td>SonarQube / ESLint</td><td>—</td></tr><tr><td>安全扫描（SAST）</td><td>CodeQL / Checkmarx</td><td>—</td></tr><tr><td>打包为发布候选</td><td>Docker / JAR / 二进制</td><td>—</td></tr></tbody></table><p>全部做完通常不超过 <strong>5 分钟</strong>。超过这个时间，开发者开始失去耐心、跳过等待、或者干脆不跑了。<a href="/testing/execution/regression-release.html">回归测试与上线标准</a>的时间预算在这里具体化了。</p><h3 id="验收阶段-验证功能正确" tabindex="-1">验收阶段：验证功能正确 <a class="header-anchor" href="#验收阶段-验证功能正确" aria-label="Permalink to &quot;验收阶段：验证功能正确&quot;">​</a></h3><p>提交阶段通过后，发布候选进入验收阶段。目标是：<strong>自动化验证&quot;功能做对了吗&quot;。</strong></p><table tabindex="0"><thead><tr><th>做什么</th><th>工具</th><th>时间预算</th></tr></thead><tbody><tr><td>所有中型测试（Q2）</td><td>Selenium / Playwright</td><td>—</td></tr><tr><td>部署到类生产环境</td><td>CI → Staging</td><td>—</td></tr><tr><td>数据库迁移验证</td><td>Flyway / Alembic</td><td>—</td></tr><tr><td>动态安全扫描（DAST）</td><td>OWASP ZAP</td><td>—</td></tr></tbody></table><p>通常控制在 <strong>1 小时以内</strong>。如果验收测试套件太大，不是放宽时间限制，而是拆分套件——核心验收和次要验收分开跑。</p><h3 id="容量阶段-验证非功能属性" tabindex="-1">容量阶段：验证非功能属性 <a class="header-anchor" href="#容量阶段-验证非功能属性" aria-label="Permalink to &quot;容量阶段：验证非功能属性&quot;">​</a></h3><p>验收通过后，候选进入容量阶段。目标是：<strong>回答&quot;系统扛得住吗、安全吗&quot;。</strong></p><table tabindex="0"><thead><tr><th>做什么</th><th>典型测试</th></tr></thead><tbody><tr><td>性能基准测试</td><td>对比历史数据，确认没有性能退化</td></tr><tr><td>压力测试</td><td>找到当前版本的承受极限</td></tr><tr><td>兼容性测试</td><td>多浏览器、多设备</td></tr></tbody></table><p>容量阶段通常需要专门的测试环境，运行时间可能数小时。这些测试不需要每次提交都跑——通常是每日构建或发布前触发。</p><h3 id="手动阶段-人类最后的判断" tabindex="-1">手动阶段：人类最后的判断 <a class="header-anchor" href="#手动阶段-人类最后的判断" aria-label="Permalink to &quot;手动阶段：人类最后的判断&quot;">​</a></h3><p>前三道闸门全是自动化的，但有些事情机器做不了——业务验收、探索式测试、易用性评估。手动阶段是管道中留给人的窗口：</p><ul><li>产品经理在这个阶段做最终的验收确认</li><li>测试人员做一轮深度探索式测试</li><li>如果发现需要修改，代码从提交阶段重新开始走一遍整个管道</li></ul><h3 id="管道和测试象限的映射" tabindex="-1">管道和测试象限的映射 <a class="header-anchor" href="#管道和测试象限的映射" aria-label="Permalink to &quot;管道和测试象限的映射&quot;">​</a></h3><p><a href="/testing/engineering/agile-testing-1.html">敏捷测试（上）</a>讲的敏捷测试四象限，在管道中各有其位：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Q1（面向技术,支持团队）──→ 提交阶段    — 单元测试、组件测试，每次提交自动跑</span></span>
<span class="line"><span>Q2（面向业务,支持团队）──→ 验收阶段    — 自动化验收测试、BDD 场景</span></span>
<span class="line"><span>Q4（面向技术,评价产品）──→ 容量阶段    — 性能、安全、兼容性</span></span>
<span class="line"><span>Q3（面向业务,评价产品）──→ 手动阶段    — 探索式测试、易用性、用户验收</span></span></code></pre></div><p>这个映射不是巧合。管道设计的本质就是把四象限的测试活动按<strong>反馈速度</strong>分层——越快的测试放越前面，越依赖人的判断放越后面。理解了四象限，你就理解了管道为什么这么排；反过来，理解了管道，你就知道四象限里每类测试该在哪里跑。</p><h3 id="管道的核心规则" tabindex="-1">管道的核心规则 <a class="header-anchor" href="#管道的核心规则" aria-label="Permalink to &quot;管道的核心规则&quot;">​</a></h3><p>Jez Humble 和 David Farley 在书中反复强调几条铁律：</p><ul><li><strong>一次构建，多次使用</strong>：提交阶段打出来的那个发布候选，验收阶段用它、容量阶段也用它、最终上线的还是它。不要在后面的阶段重新构建——否则你上线的东西不是你测过的东西</li><li><strong>任何阶段失败，整个管道停止</strong>：不存在&quot;提交阶段挂了但验收阶段的测试已经跑了一半我们跳过看看&quot;</li><li><strong>人工审批只放在最后</strong>：前面的自动化阶段不应有人工审批——自动化通过了就自动往下走。只有最后的手动阶段到生产发布之间加一道人的&quot;确认&quot;按钮</li></ul><h3 id="部署-发布" tabindex="-1">部署 ≠ 发布 <a class="header-anchor" href="#部署-发布" aria-label="Permalink to &quot;部署 ≠ 发布&quot;">​</a></h3><p>《持续交付》做了一个重要的区分，很多人混着用：</p><ul><li><strong>部署（Deployment）</strong>：把代码放到生产环境的服务器上</li><li><strong>发布（Release）</strong>：让用户真正能用</li></ul><p>这两者可以不发生在同一时间。通过<strong>特性开关（Feature Flag）</strong>，你可以先把代码部署到生产环境，但让开关处于关闭状态——用户看不到新功能。部署后观察一段时间，确认监控指标正常，再打开开关完成发布。发现异常，一键关闭开关就行，不需要回滚整个部署。</p><p>这个区分配合管道的最后一环，让&quot;上线&quot;从一次孤注一掷变成了<strong>可控的风险释放</strong>。管道给了你信心（经过了提交→验收→容量验证），特性开关给了你最后的控制力。这也是<a href="/testing/execution/regression-release.html">回归测试与上线标准</a>爬-走-跑灰度发布背后的技术支撑。</p><h2 id="八大核心原则" tabindex="-1">八大核心原则 <a class="header-anchor" href="#八大核心原则" aria-label="Permalink to &quot;八大核心原则&quot;">​</a></h2><p>《持续交付》总结了八条原则，它们是整个方法论的地基。</p><h3 id="_1-一切纳入版本控制" tabindex="-1">1. 一切纳入版本控制 <a class="header-anchor" href="#_1-一切纳入版本控制" aria-label="Permalink to &quot;1. 一切纳入版本控制&quot;">​</a></h3><p>不只是源代码。构建脚本、数据库 Schema、环境配置、基础设施定义——凡是能决定系统行为的东西，全部进版本控制。</p><p>如果你换了一台全新的机器，签出代码、跑一条命令就能构建和运行整个系统——说明版本控制做到了位。如果你还需要&quot;哦对了你还要装一个 Python 3.8、然后手动配一下数据库连接&quot;，那就没做到位。</p><h3 id="_2-只构建一次" tabindex="-1">2. 只构建一次 <a class="header-anchor" href="#_2-只构建一次" aria-label="Permalink to &quot;2. 只构建一次&quot;">​</a></h3><p>就是上面说的铁律。提交阶段构建出的二进制包或 Docker 镜像，在后续所有阶段中使用，绝不重新构建。</p><p>为什么这么重要？因为重新构建意味着引入变量——编译环境可能不同、依赖版本可能漂移、配置可能不一致。你在测试环境验证通过的那个二进制和最终上线的是同一个东西，才能说&quot;我测过的就是这个&quot;。</p><h3 id="_3-同一套流程部署所有环境" tabindex="-1">3. 同一套流程部署所有环境 <a class="header-anchor" href="#_3-同一套流程部署所有环境" aria-label="Permalink to &quot;3. 同一套流程部署所有环境&quot;">​</a></h3><p>测试环境、预发布环境、生产环境——部署方式应该完全一样。唯一区别只是配置参数（数据库地址、密钥等），而配置也是版本控制的。</p><p>如果生产环境是&quot;运维手动 SSH 上去改配置&quot;，测试环境是&quot;开发一键脚本部署&quot;，那你在测试环境验证通过的东西在生产环境可能完全不一样。</p><h3 id="_4-自动化几乎一切" tabindex="-1">4. 自动化几乎一切 <a class="header-anchor" href="#_4-自动化几乎一切" aria-label="Permalink to &quot;4. 自动化几乎一切&quot;">​</a></h3><p>构建、测试、部署、环境准备、数据迁移——凡是重复执行的，都应该自动化。</p><p>自动化不只是&quot;省时间&quot;，更是<strong>消除人为错误</strong>。人手动操作，总有一步会忘记、一个参数会写错。脚本不会忘，每次执行都是完全一样的流程。</p><h3 id="_5-尽早且频繁提交" tabindex="-1">5. 尽早且频繁提交 <a class="header-anchor" href="#_5-尽早且频繁提交" aria-label="Permalink to &quot;5. 尽早且频繁提交&quot;">​</a></h3><p>每写完一个小功能就提交，而不是憋了三天才提交一次。提交越频繁，每次提交的变更越小，出了问题定位越快。你的提交变成了一个精确的&quot;时间点快照&quot;，而不是一大坨混乱的改动。</p><h3 id="_6-每次提交都触发管道" tabindex="-1">6. 每次提交都触发管道 <a class="header-anchor" href="#_6-每次提交都触发管道" aria-label="Permalink to &quot;6. 每次提交都触发管道&quot;">​</a></h3><p>这不是&quot;建议&quot;，是管道的定义。每次提交自动触发完整的验证流程。如果你需要手动去点&quot;开始测试&quot;，一定会有人忘记点。</p><h3 id="_7-建立最短反馈循环" tabindex="-1">7. 建立最短反馈循环 <a class="header-anchor" href="#_7-建立最短反馈循环" aria-label="Permalink to &quot;7. 建立最短反馈循环&quot;">​</a></h3><p>持续交付的根本目标是缩短&quot;写代码 → 知道它有没有问题&quot;的时间。提交阶段几分钟反馈、验收阶段几十分钟反馈——越快知道，修复成本越低。</p><h3 id="_8-质量内建" tabindex="-1">8. 质量内建 <a class="header-anchor" href="#_8-质量内建" aria-label="Permalink to &quot;8. 质量内建&quot;">​</a></h3><p>不要依赖最后的检查来保证质量。从需求、设计、编码、测试每一步都把质量做进去。测试不是事后把关，是整个过程的一部分。<a href="/testing/basics/what-is-testing.html">重新认识软件测试</a>讲的&quot;质量 ≠ 测试&quot;，到这里有了工程实践上的回答——管道就是质量内建的骨架。</p><h2 id="配置管理-原则第一条的落地" tabindex="-1">配置管理：原则第一条的落地 <a class="header-anchor" href="#配置管理-原则第一条的落地" aria-label="Permalink to &quot;配置管理：原则第一条的落地&quot;">​</a></h2><p>&quot;一切纳入版本控制&quot;说起来容易，做起来有几个坑。</p><h3 id="哪些东西经常被漏掉" tabindex="-1">哪些东西经常被漏掉 <a class="header-anchor" href="#哪些东西经常被漏掉" aria-label="Permalink to &quot;哪些东西经常被漏掉&quot;">​</a></h3><table tabindex="0"><thead><tr><th>被漏掉的东西</th><th>后果</th></tr></thead><tbody><tr><td>数据库 Schema</td><td>测试环境和生产环境的表结构不同，代码在测试环境跑得好好的，上线就 SQL 报错</td></tr><tr><td>第三方依赖的版本</td><td>你这台机器装的 pandas 1.5、CI 上装的是 1.4，行为不一样</td></tr><tr><td>环境配置文件</td><td>&quot;这个 YAML 是测试环境的，那个是生产的&quot;——但它们不在版本控制里，只在某人的电脑上</td></tr><tr><td>部署脚本</td><td>&quot;部署是小王手动做的，他知道怎么操作&quot;——小王离职了就没人知道了</td></tr></tbody></table><h3 id="配置和代码分离" tabindex="-1">配置和代码分离 <a class="header-anchor" href="#配置和代码分离" aria-label="Permalink to &quot;配置和代码分离&quot;">​</a></h3><p>版本控制不等于&quot;把密码也提交到 GitHub&quot;。配置分两层：</p><ul><li><strong>代码级配置</strong>（端口号、超时时间、日志级别）→ 进入版本控制，和代码一起</li><li><strong>敏感配置</strong>（数据库密码、API 密钥）→ 进版本控制的是<strong>模板或占位符</strong>，真实值通过环境变量或密钥管理服务注入</li></ul><blockquote><p>一个简单的判断标准：找一台全新的机器，只从版本控制签出代码，按 README 里的步骤执行，能不能把系统跑起来？如果能，原则一就到位了。</p></blockquote><h2 id="本章小结" tabindex="-1">本章小结 <a class="header-anchor" href="#本章小结" aria-label="Permalink to &quot;本章小结&quot;">​</a></h2><ol><li>部署管道是自动化质量验证链条——提交→验收→容量→手动→生产，各阶段对应 Q1→Q2→Q4→Q3，按反馈速度分层</li><li>一条铁律：一次构建，整个管道使用同一个发布候选，绝不重新构建</li><li>部署 ≠ 发布：部署是把代码放上生产服务器，发布是让用户能用。特性开关让两者解耦，上线从孤注一掷变成可控的风险释放</li><li>八条原则中最核心的三条：一切纳入版本控制、自动化几乎一切、建立最短反馈循环</li><li>配置管理不是&quot;配置文件放对位置&quot;——是让一台全新的机器签出代码后就能跑起来</li></ol>`,67)])])}const c=a(n,[["render",d]]);export{q as __pageData,c as default};
